sql.where:

AND o.id_user = #{userId}

    AND o.code = #{code}


    AND o.pay_status = #{payStatus}


    AND o.order_status = #{orderStatus}


    AND o.create_at >= #{createAtEarliest}


    AND o.create_at <= #{createAtLatest}


    AND f.region_dep = #{regionDep}


    AND f.region_arr = #{regionArr}


    AND a.name = #{airlineName}
